{
  "meta": {
    "name": "主线剧情时间线 - 第一卷 (V8.1导演剧本修正版)",
    "version": "8.1",
    "description": "格式说明：本文件为AI叙事引擎的剧本。`事件链`是大的故事章节，`阶段`是章节下的小节。`阶段背景`定义了剧情发生前角色和世界的认知与状态。`触发条件`是程序判断是否激活该剧情的依据。`关键情节`是AI在本阶段必须表演的核心内容。`NPC剧本`是角色的表演指导。`必然变量变更`是阶段一旦触发就必须执行的事件，`默认演化`则是在玩家无干预时，世界自动发生的事情。",
    "schema_definition": {
      "id": "事件链的唯一ID",
      "事件链背景": "Array<String>",
      "章节核心目标": "String",
      "阶段": [
        {
          "id": "阶段的唯一ID",
          "阶段摘要": "String",
          "阶段背景": "Array<String>",
          "触发条件": "{ '必须全部满足': Array<String> }",
          "关键人物": "Array<String>",
          "关键地点": "Array<String>",
          "关键道具": "Array<String>",
          "场景修饰": "Array<String>",
          "NPC剧本": "{ '角色名': {'认知':Array<String>, '心态':String, '行动指引':String} }",
          "关键情节": [{ "id": "情节的唯一ID", "描述": "String" }],
          "必然变量变更": "Array<String>",
          "默认演化": {
            "描述": "String",
            "变量变更": "Array<String>"
          }
        }
      ],
      "章节终止条件": "Array<String>"
    }
  },
  "timeline": [
    {
      "id": "M0.1",
      "事件链背景": [
        "【核心矛盾】：这是一个关于“青春的定义”以及“孤独之人”如何自处的故事的开端。",
        "【侍奉部状态】：不存在。",
        "【核心关系】：比企谷八幡、雪之下雪乃、由比滨结衣互相不认识。"
      ],
      "章节核心目标": "通过一场车祸和一篇扭曲的作文，塑造比企谷八幡的孤高性格，并为他与雪之下雪乃、由比滨结衣的命运交错，以及侍奉部的建立埋下伏笔。",
      "阶段": [
        {
          "id": "M0.1-1",
          "阶段摘要": "比企谷八幡为救一只小狗而被高级轿车撞伤。",
          "阶段背景": ["【世界状态】：总武高开学典礼当天，一切都还是全新的开始。"],
          "触发条件": { "必须全部满足": ["日期为 2012-04-08", "时间片段为 上学路"] },
          "关键人物": ["比企谷八幡", "由比滨结衣", "雪之下雪乃"],
          "关键地点": ["总武高校门口区域"],
          "关键道具": ["由比滨的狗", "雪之下的豪车"],
          "场景修饰": ["樱花飞舞", "刺眼的阳光", "紧急刹车声", "少女的惊呼"],
          "NPC剧本": {
            "比企谷八幡": {
              "认知": ["今天是高中开学第一天。", "眼前这个女孩（由比滨）不认识。", "冲过来的车是高级轿车。"],
              "心态": "对即将到来的“青春”生活充满悲观和不屑，认为这一切都是虚伪的。",
              "行动指引": "在看到小狗即将被撞时，身体会先于大脑行动冲出去，事后会用自己的一套扭曲逻辑来解释自己的行为。"
            },
            "由比滨结衣": {
              "认知": ["自己的爱犬“萨布雷”挣脱了狗绳。", "一个不认识的男生为了救自己的狗被车撞了。"],
              "心态": "极度的惊慌、恐惧和内疚。",
              "行动指引": "发出惊呼，在事故发生后立刻冲向自己的狗，然后才意识到救狗的男生受了伤，表现出不知所措。"
            },
            "雪之下雪乃": {
              "认知": [
                "乘坐家里的车去参加开学典礼。",
                "车子似乎撞到了什么人。",
                "那个救狗的男生和狗主人看起来都是本校的学生。"
              ],
              "心态": "冷静、漠然，如同一个与此事无关的旁观者。",
              "行动指引": "从车窗内投出冰冷、清澈且毫无波澜的眼眸，观察着事故现场的每一个人，像是在分析一件事物。"
            }
          },
          "关键情节": [
